int devif_poll_out(FAR struct net_driver_s *dev,
                   devif_poll_callback_t callback)
{
  int bstop;

  if (dev->d_len == 0)
    {
      return 0;
    }

  devif_out(dev);

  bstop = devif_loopback(dev);
  if (bstop || dev->d_len == 0)
