  gm_putreg(priv, RK3576_GMAC_MTL_TXQ0_OPERATION_MODE,
            RK3576_GMAC_MTL_TXQ0_TSF | RK3576_GMAC_MTL_TXQ0_TXQEN_ENABLE);
