/* The same for the transmit side: a frame the MAC gave up on completes its
 * descriptor like any other, so the only trace it leaves is the status word
 * the reaper throws away.
 */

bool txfaulted;

static void gm_tx_reap(FAR struct rk3576_gmac_s *priv)
{
  FAR struct rk3576_gmac_desc_s *desc;
  uint32_t status;

  while (priv->txnow != priv->txdone)
    {
      desc = gm_desc(priv->txring, priv->txdone);
      gm_desc_inval(desc);

      status = desc->des3;
      if ((status & RK3576_GMAC_TDES3_OWN) != 0)
        {
          break;
        }

      /* The frame is finished, not necessarily sent: a frame the MTL could
       * not hold -- an underflow -- completes its descriptor with ES (and UF)
       * set in the write-back word, and the frame that reached the wire is
       * truncated, so the peer drops it as damaged and nothing on either side
       * counts it.  Say it once, with the word that explains it.
       */

      if ((status & RK3576_GMAC_TDES3_ES) != 0 && !priv->txfaulted)
        {
          priv->txfaulted = true;
          syslog(LOG_ERR, "gmac%d: TX frame failed, TDES3 0x%08" PRIx32 "\n",
                 priv->intf, status);
        }

      netpkt_free(&priv->dev, priv->txpkt[priv->txdone], NETPKT_TX);
      priv->txpkt[priv->txdone] = NULL;
      priv->txdone = (priv->txdone + 1) % GM_TX_DESC;
    }
}

