static void wget_dump(FAR const uint8_t *buf, size_t len)
{
  char hex[3 * 24 + 1];
  char txt[24 + 1];
  size_t i;

  for (i = 0; i < len && i < 96; i += 24)
    {
      size_t n = len - i < 24 ? len - i : 24;
      size_t j;

      for (j = 0; j < n; j++)
        {
          snprintf(&hex[3 * j], 4, "%02x ", buf[i + j]);
          txt[j] = buf[i + j] >= 0x20 && buf[i + j] < 0x7f ? buf[i + j] : '.';
        }

      hex[3 * n] = '\0';
      txt[n] = '\0';
      nerr("HTTP> %s |%s|\n", hex, txt);
    }
}
```
