/****************************************************************************
 * Name: wget_resolve_relative
 *
 * Description:
 *   Turn a relative Location header into the path of the target it belongs to.
 *
 *   A Location may be relative -- RFC 7231 7.1.2 leaves the form open, and a
 *   PHP application answers "302 Found" with "/index.php" as often as not.
 *   netlib_parseurl() only accepts an absolute URL, so before this the request
 *   died with EINVAL and no message at all: the only warning on that path is
 *   printed for the URL the caller gave, not for a header.
 *
 * Returned Value:
 *   Zero on success, -E2BIG if the result does not fit the target's buffer.
 *
 ****************************************************************************/

static int wget_resolve_relative(FAR const char *loc,
                                 FAR struct wget_target_s *targ)
{
  char path[CONFIG_WEBCLIENT_MAXFILENAME];
  FAR const char *base = targ->filename;
  size_t baselen;

  if (loc[0] == '/')
    {
      /* An absolute path on the same host: that is the whole answer. */

      baselen = 0;
    }
  else if (loc[0] == '?')
    {
      /* Query only: the path stays, the old query goes. */

      FAR const char *query = strchr(base, '?');

      baselen = query != NULL ? (size_t)(query - base) : strlen(base);
    }
  else
    {
      /* Relative to the directory the current path is in. */

      FAR const char *slash = strrchr(base, '/');

      baselen = slash != NULL ? (size_t)(slash - base) + 1 : 0;
    }

  if (baselen + strlen(loc) + 1 > sizeof(path))
    {
      return -E2BIG;
    }

  if (loc[0] == '/')
    {
      strlcpy(path, loc, sizeof(path));
    }
  else
    {
      memcpy(path, base, baselen);
      strlcpy(path + baselen, loc, sizeof(path) - baselen);
    }

  strlcpy(targ->filename, path, sizeof(targ->filename));
  return OK;
}

